'use strict';
// Shared, bounded in-game panels: all actions remain outside scrolling content.
function journeyPanel(title,body,footer){openModal('<h2>'+esc(title)+'</h2><div class="journey-panel-content">'+body+'</div><div class="journey-panel-footer">'+footer+'</div>');const panel=document.querySelector('#overlay>.modal');panel.classList.add('journey-panel');panel.setAttribute('role','dialog');panel.setAttribute('aria-modal','true');panel.setAttribute('aria-label',title);}
(function(){
 const J=JourneyDebug,A=JourneyActs,orders={ironbound:{en:"Grand Union",pt:"Grand Union"},monsters:{en:'Titans',pt:'Titans'},blackfang:{en:'Blackfang',pt:'Blackfang'},dawncrest:{en:'Dawncrest',pt:'Dawncrest'}};
 const deckNames={blackfang_goblins:'Goblin Incursion',blackfang_brutal:'Brutal Vanguard',blackfang_shadows:'Shadow Company',blackfang_boss:'Blackfang Court',dawncrest_felines:'Meowri Company',dawncrest_sentinels:'Dawn Sentinels',dawncrest_woodlands:'Forest Patrol',dawncrest_boss:'Dawncrest Court'};
 function encounterName(e){if(e.raidKind&&JourneyRaid.SPECS[e.raidKind]){const d=JourneyRaid.SPECS[e.raidKind];return L(d.en,d.pt);}const d=[...G.BLACKFANG_DECKS,...G.DAWNCREST_DECKS].find(d=>d.id===e.forceId);return d?L(deckNames[d.id]||d.name,d.name):L('Order encounter','Encontro de ordem');}
 function history(order){const rows=A.orderHistory(S),total=A.orderTotals(S)[order];journeyPanel(L('Order history','Histórico da ordem'),'<div class="order-history-title">'+orderMark(order)+'<b>'+L(orders[order].en,orders[order].pt)+' · '+total+'/6</b></div>'+rows.map(h=>{const d=JourneyBosses.D[h.bossId],boss=d?L(d.en,d.pt):h.raidKind&&JourneyRaid.SPECS[h.raidKind]?L(JourneyRaid.SPECS[h.raidKind].en,JourneyRaid.SPECS[h.raidKind].pt):h.order?L(orders[h.order].en,orders[h.order].pt):L('Passage guardian','Guardião da passagem');return '<article class="order-history-map"><div><h3>'+L('Map ','Mapa ')+h.act+'</h3><b>'+(h.visited?h.counts[order]+'/2':'—')+'</b></div>'+h.encounters.filter(e=>e.order===order).map(e=>'<p>✓ '+esc(encounterName(e))+'</p>').join('')+'<small>'+(h.completed?L('Boss defeated: ','Boss derrotado: ')+esc(boss):h.current?L('Current map · Boss not defeated','Mapa atual · Boss não derrotado'):h.visited?L('Boss not defeated','Boss não derrotado'):L('Not visited','Não visitado'))+'</small></article>';}).join('')+'<p class="panel-hint">'+L('True Final Boss: defeat the same order’s Boss in maps 1 and 2, then both encounters of that order in map 3. Totals alone do not determine the final boss.','True Final Boss: derrote o Boss da mesma ordem nos mapas 1 e 2 e os dois encontros dessa ordem no mapa 3. O total isolado não define o boss final.')+'</p>',metaButton('close',L('Back','Voltar'),'','primary'));}
 function finishJump(ok){if(!ok)return toast(L('Finish combat, the Relic Bag, or the skill tree before jumping.','Conclua o combate, a bolsa ou a árvore antes de saltar.'));cancelAnimationFrame(raf);battle=null;runRaidPending=null;selected=null;paused=false;closeModal();save();render();}
 function mapPicker(){journeyPanel(L('Jump to map','Ir direto ao mapa'),'<p class="panel-hint">'+L('Keeps your deck, relics, gold and XP. Skipped encounters grant no victories or rewards.','Mantém seu deck, relíquias, ouro e XP. Encontros pulados não concedem vitórias nem recompensas.')+'</p><div class="stack">'+[1,2,3].map(a=>metaButton('debug-map-jump',L('Map ','Mapa ')+a+(a===A.act(S)?' · '+L('current','atual'):''),'data-map="'+a+'"','secondary')).join('')+'</div>',metaButton('hacks',L('Back','Voltar')));}
 function nodePicker(){journeyPanel(L('Choose map node','Escolher node do mapa'),'<p class="panel-hint">'+L('Map ','Mapa ')+A.act(S)+L(' · Enter any node directly. No route required.',' · Entre direto em qualquer node, sem percorrer a rota.')+'</p><div class="debug-node-list">'+S.map.map((row,i)=>'<section><h3>'+L('Layer ','Camada ')+(i+1)+'</h3>'+row.map(n=>{const order=n.campaign&&orders[n.campaign],d=n.type==='boss'&&n.bossId?JourneyBosses.D[n.bossId]:null,caption=d?L(d.en,d.pt):n.campaign==='monsters'?L(JourneyRaid.SPECS[n.raidKind||'tree'].en,JourneyRaid.SPECS[n.raidKind||'tree'].pt):order?L(order.en,order.pt):mapType(n.type);return '<button class="debug-node-choice" data-act="debug-node-jump" data-id="'+n.id+'">'+nodeSymbol(n)+'<span><b>'+esc(caption)+'</b><small>'+mapType(n.type)+' · '+L('Position ','Posição ')+(n.lane+1)+'</small></span><span>›</span></button>';}).join('')+'</section>').join('')+'</div>',metaButton('hacks',L('Back','Voltar')));}
 const hacks=hacksView;hacksView=function(){hacks();const can=J.allowed(S)&&(!battle||battle.result),reason=can?'':L('Start a run and finish combat, the Relic Bag or skill tree first.','Inicie uma run e conclua o combate, a bolsa ou a árvore primeiro.');document.querySelector('#overlay>.modal .stack').insertAdjacentHTML('afterbegin',metaButton('debug-map-open',L('Jump to map','Ir direto ao mapa'),guardAttrs(reason))+metaButton('debug-node-open',L('Choose map node','Escolher node do mapa'),guardAttrs(reason)));const modal=document.querySelector('#overlay>.modal'),stack=modal.querySelector('.stack'),back=stack.querySelector('[data-act="menu"]'),content=document.createElement('div'),footer=document.createElement('div');modal.classList.add('journey-panel');content.className='journey-panel-content';footer.className='journey-panel-footer';footer.append(back);for(const child of [...modal.children])if(!child.matches('.close,h2'))content.append(child);modal.append(content,footer);};
 const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]'),act=el?.dataset.act;if(!['order-history','debug-map-open','debug-map-jump','debug-node-open','debug-node-jump'].includes(act))return guard(e);if(e.type!=='click')return guard(e);e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return true;if(el.dataset.block){toast(el.dataset.block);return true;}if(act==='order-history')history(el.dataset.id);else if(act==='debug-map-open')mapPicker();else if(act==='debug-node-open')nodePicker();else if(act==='debug-map-jump')finishJump(J.jumpMap(S,Number(el.dataset.map)));else finishJump(J.jumpNode(S,el.dataset.id));return true;};
})();
